const unwrap = (it) => { const j = it.json; const p = (j && j.data) ? j.data : j; return Array.isArray(p) ? p[0] : p; };
const items = $input.all().map(unwrap);
const AS = items.find(x => x && x.stage === 'WF-11');
const CL = items.find(x => x && x.stage === 'WF-12');
if (!AS || !CL) throw new Error('Missing WF-11 or WF-12 input');

const A = AS.assertions;
const C = CL.clusters;
const idx = (m,k) => (m[k] && typeof m[k].index === 'number') ? Math.max(0, m[k].index) : 0;
const wt  = (m,k) => (m[k] && typeof m[k].weighted === 'number') ? m[k].weighted : 0;
const ev  = (m,k) => (m[k] && m[k].evidence_ids) ? m[k].evidence_ids : [];

// Rank-percentile normalisation. Spreads a distribution across 0..1 regardless of
// outliers. Replaces max-normalisation, which collapsed 47 of 53 worlds into a
// narrow band and made the model non-discriminating (defect DEF-01).
const rankNorm = (vals) => {
  const uniq = [...new Set(vals)].sort((a,b)=>a-b);
  const m = new Map();
  uniq.forEach((v,i)=> m.set(v, uniq.length > 1 ? i/(uniq.length-1) : 0.5));
  return m;
};

// ---- world context maps ----
const worldGenres={}, worldEngines={}, worldEvidence={}, engineEvidence={}, worldSupplyW={};
for (const a of A) {
  if (a.assertion_type === 'supply' && a.world) {
    const w=a.world;
    worldGenres[w]=worldGenres[w]||new Set();
    worldEngines[w]=worldEngines[w]||new Set();
    worldEvidence[w]=worldEvidence[w]||new Set();
    (a.genres||[]).forEach(g=>worldGenres[w].add(g));
    (a.engines||[]).forEach(e=>{worldEngines[w].add(e); engineEvidence[e]=engineEvidence[e]||new Set(); engineEvidence[e].add(a.evidence_id);});
    worldEvidence[w].add(a.evidence_id);
    worldSupplyW[w]=(worldSupplyW[w]||0)+a.weight;
  }
}

const ARCHETYPE = { bbc:'public_service', channel_4:'public_service',
  itv:'commercial_fta', itvx:'commercial_fta', channel_5:'commercial_fta', itv_studios:'commercial_fta',
  netflix:'streamer', sky:'streamer', apple_tv:'streamer', hbo:'streamer', peacock:'streamer', bravo:'streamer',
  britbox:'niche_channel', acorn_tv:'niche_channel', true_crime_channel:'niche_channel' };

const routeOpen={};
for (const a of A) if (a.assertion_type==='route') {
  const rt=a.route_type||'unspecified';
  routeOpen[rt]=(routeOpen[rt]||0)+a.weight*a.direction_value;
}
const maxRoute=Math.max(1e-9, ...Object.values(routeOpen).map(Math.abs));
const rnorm=(k)=>(routeOpen[k]||0)/maxRoute;

let indieOpen=0, indieW=0;
for (const f of (CL.format_trend_signals||[])) {
  const t=(f.interpretation||'')+' '+(f.metric||'');
  if (/independent|indie|empower/i.test(t)) indieOpen+=f.weight;
  indieW+=f.weight;
}
const indieOpenness = indieW>0 ? Math.min(1, 0.5+0.5*(indieOpen/indieW)) : 0.5;

const ARCH_ROUTE = {
  public_service: Math.max(0, rnorm('open_free')),
  commercial_fta: 0.35,
  streamer: Math.max(0.05, 1 + rnorm('closed')),
  niche_channel: 0.45,
  direct_app: indieOpenness
};

const formatDemand = C.format_demand||{};
const formats = Object.keys(formatDemand).filter(f=>f!=='mixed');
const FORMAT_FEASIBILITY = { vertical_microdrama:1.0, limited_series:0.6, returnable_series:0.45 };

const buyerFormat = C.buyer_format||{};
const formatArchetypes={};
for (const k of Object.keys(buyerFormat)) {
  const [b,f]=k.split('|');
  const arch=ARCHETYPE[b]||'commercial_fta';
  formatArchetypes[f]=formatArchetypes[f]||{};
  formatArchetypes[f][arch]=Math.max(formatArchetypes[f][arch]||0, buyerFormat[k].index);
}
formatArchetypes['vertical_microdrama']={ direct_app:1.0 };

const buyerGenre=C.buyer_genre||{}, genreDemand=C.genre_demand||{}, genreSupply=C.genre_supply||{},
      audienceByGenre=C.audience_by_genre||{};

// ---- per-world derived measures ----
const worlds = Object.keys(worldGenres).filter(w => worldGenres[w].size > 0);
const demandCtxRaw={}, underServeRaw={}, breadthRaw={};
for (const w of worlds) {
  const gs=Array.from(worldGenres[w]);
  const gd=gs.reduce((s,g)=>s+Math.max(0,wt(genreDemand,g)),0)/Math.max(1,gs.length);
  const ga=gs.reduce((s,g)=>s+Math.max(0,wt(audienceByGenre,g)),0)/Math.max(1,gs.length);
  demandCtxRaw[w]=gd+ga;
  underServeRaw[w]=(gd+ga)/(1+(worldSupplyW[w]||0));
  breadthRaw[w]=(worldEvidence[w]?worldEvidence[w].size:0);
}
const usMap=rankNorm(worlds.map(w=>underServeRaw[w]));
const satMap=rankNorm(worlds.map(w=>worldSupplyW[w]||0));
const brMap=rankNorm(worlds.map(w=>breadthRaw[w]));

const territoriesByGenre={};
for (const a of A) if (a.assertion_type==='buyer_demand' && a.territory)
  for (const g of (a.genres||[])) { territoriesByGenre[g]=territoriesByGenre[g]||new Set(); territoriesByGenre[g].add(a.territory); }

const mean=(x)=>x.length?x.reduce((a,b)=>a+b,0)/x.length:0;
const costPressure=CL.cost_pressure_index||0;
const legalFlagged=CL.legal_flagged_worlds||{};

const WEIGHTS={ buyer_demand:18, route_accessibility:18, production_feasibility:15,
  under_service:12, audience_demand:10, saturation_inverse:10, buyer_fit:7,
  international_potential:5, evidence_breadth:5 };

const scored=[];
for (const w of worlds) {
  const gs=Array.from(worldGenres[w]);
  const es=Array.from(worldEngines[w]);
  if (!es.length) continue;
  for (const e of es) for (const f of formats) {
    const gDemand=mean(gs.map(g=>idx(genreDemand,g)));
    const gAudience=mean(gs.map(g=>idx(audienceByGenre,g)));
    const gSupply=mean(gs.map(g=>idx(genreSupply,g)));
    const fDemand=idx(formatDemand,f);

    const archs=formatArchetypes[f]||{commercial_fta:0.5};
    let routeScore=0;
    for (const [arch,aff] of Object.entries(archs))
      routeScore=Math.max(routeScore,(ARCH_ROUTE[arch]||0.3)*(0.5+0.5*aff));

    const baseFeas=FORMAT_FEASIBILITY[f]!==undefined?FORMAT_FEASIBILITY[f]:0.5;
    const feas=Math.min(1, baseFeas*(1+costPressure*0.5));

    let bFit=0;
    for (const g of gs) for (const b of Object.keys(ARCHETYPE)) {
      const k=b+'|'+g; if (buyerGenre[k]) bFit=Math.max(bFit,buyerGenre[k].index);
    }
    const terr=mean(gs.map(g=>territoriesByGenre[g]?territoriesByGenre[g].size:0));

    const dims={
      buyer_demand: fDemand*0.6+gDemand*0.4,
      route_accessibility: routeScore,
      production_feasibility: feas,
      under_service: usMap.get(underServeRaw[w]),
      audience_demand: gAudience,
      saturation_inverse: 1-(0.5*satMap.get(worldSupplyW[w]||0)+0.5*Math.min(1,gSupply)),
      buyer_fit: bFit,
      international_potential: Math.min(1,terr/3),
      evidence_breadth: brMap.get(breadthRaw[w])
    };

    let total=0; const contrib={};
    for (const [k,g] of Object.entries(WEIGHTS)) {
      const v=Math.max(0,Math.min(1,dims[k]||0));
      contrib[k]=Number((v*g).toFixed(2)); total+=v*g;
    }

    const support=Array.from(new Set([].concat(
      Array.from(worldEvidence[w]||[]), Array.from(engineEvidence[e]||[]),
      ev(formatDemand,f), ...gs.map(g=>ev(genreDemand,g))
    ))).slice(0,14);

    scored.push({
      intersection_id:[w,e,f].join('__'), world:w, engine:e, format:f, genres:gs,
      score_total:Number(total.toFixed(2)),
      score_vector:Object.fromEntries(Object.entries(dims).map(([k,v])=>[k,Number(Math.max(0,Math.min(1,v||0)).toFixed(3))])),
      score_contribution:contrib,
      world_supply_weight:Number((worldSupplyW[w]||0).toFixed(2)),
      world_demand_context:Number(demandCtxRaw[w].toFixed(2)),
      world_evidence_count:breadthRaw[w],
      evidence_support:support, evidence_support_count:support.length,
      legal_flag_count:legalFlagged[w]||0,
      scoring_model_version:'SCORING_MODEL_V2'
    });
  }
}
scored.sort((a,b)=>b.score_total-a.score_total);

const fmtAgg={};
for (const s of scored) { fmtAgg[s.format]=fmtAgg[s.format]||[]; fmtAgg[s.format].push(s.score_total); }

return [{ json:{
  stage:'WF-13', generated_at:new Date().toISOString(),
  scoring_model_version:'SCORING_MODEL_V2',
  repair_note:'V2 replaces max-normalisation with rank-percentile normalisation (defect DEF-01) and replaces originality_space with under_service = world demand context / (1 + world supply).',
  known_limitation:'Candidate worlds are drawn only from supply assertions, so every scored world is already in commission. The corpus cannot surface a zero-supply world. See DEF-02.',
  weights:WEIGHTS, archetype_route_openness:ARCH_ROUTE, cost_pressure_index:costPressure,
  format_pool:formats, candidate_count:scored.length, worlds_considered:worlds.length,
  format_summary:Object.fromEntries(Object.entries(fmtAgg).map(([k,v])=>[k,{mean:Number((v.reduce((a,b)=>a+b,0)/v.length).toFixed(2)),max:Number(Math.max(...v).toFixed(2)),n:v.length}])),
  opportunities:scored
}}];
